def producer_metric_controller_inverse(raw):
    raw = source_parent_controller_inverse(raw)
    spec = PRODUCER_METRIC_CONTROLLER_INVERSE
    binary = isinstance(raw, bytes)
    text = raw.decode() if binary else raw
