def startup_controller_inverse(raw):
    raw = clock_failure_controller_inverse(raw)
    for row in reversed(STARTUP_OBSERVABILITY_HISTORY['rows']):
        new, old = row['newRaw'].encode(), row['oldRaw'].encode()
        assert hashlib.sha256(new).hexdigest() == row['newSha256']
        assert hashlib.sha256(old).hexdigest() == row['oldSha256']
        assert raw.count(new) == 1
        raw = raw.replace(new,old,1)
    assert len(raw) == STARTUP_OBSERVABILITY_HISTORY['bytes']
    assert hashlib.sha256(raw).hexdigest() == STARTUP_OBSERVABILITY_HISTORY['sha256']
    return raw
