def full_source_image_inverse(raw):
    raw = source_acquisition_inverse(raw, "driver")
    text = raw.decode()
    for row in FULL_SOURCE_IMAGE_INVERSE['rows']:
        assert hashlib.sha256(row['newRaw'].encode()).hexdigest() == row['newSha256'], 'ASSEMBLY_INVERSE_FULL_IMAGE_PIN'
        assert hashlib.sha256(row['oldRaw'].encode()).hexdigest() == row['oldSha256'], 'ASSEMBLY_INVERSE_FULL_IMAGE_PIN'
        assert text.count(row['newRaw']) == 1, 'ASSEMBLY_INVERSE_FULL_IMAGE_COUNT'
        text = text.replace(row['newRaw'], row['oldRaw'], 1)
    assert len(text.encode()) == FULL_SOURCE_IMAGE_INVERSE['bytes'] and hashlib.sha256(text.encode()).hexdigest() == FULL_SOURCE_IMAGE_INVERSE['sha256'], 'ASSEMBLY_INVERSE_FULL_IMAGE_WHOLE'
    return text.encode()
# END EXACT FULL SOURCE IMAGE INVERSE

def assembly_inverse(raw, name):
    if name == "driver":
        raw = full_source_image_inverse(raw)
    if name == "controller":
        raw = startup_controller_inverse(raw)
    spec = ASSEMBLY_HISTORY[name]
    for row in reversed(spec['rows']):
        current, old = row['newRaw'].encode(), row['oldRaw'].encode()
        assert hashlib.sha256(current).hexdigest() == row['newSha256'] and hashlib.sha256(old).hexdigest() == row['oldSha256'], 'ASSEMBLY_INVERSE_PIN'
        assert raw.count(current) == 1, 'ASSEMBLY_INVERSE:' + row['name']
        raw = raw.replace(current, old, 1)
    assert len(raw) == spec['bytes'] and hashlib.sha256(raw).hexdigest() == spec['sha256'], 'ASSEMBLY_INVERSE_WHOLE'
    return raw
# END FINITE ASSEMBLY HISTORY

def source_program_inverse(raw):
    if b"// BEGIN SOURCE OWNED DEPOT TOOLS SENTINEL NORMALIZATION" in raw:
        raw = assembly_inverse(raw, "driver")
    for row in SOURCE_PROGRAM_HISTORY:
        current, old = row["newRaw"].encode(), row["oldRaw"].encode()
        if hashlib.sha256(current).hexdigest() != row["newSha256"] or hashlib.sha256(old).hexdigest() != row["oldSha256"] or raw.count(current) != 1:
            raise AssertionError("SOURCE_PROGRAM_INVERSE:" + row["name"])
        raw = raw.replace(current, old, 1)
    return raw


