def full_metadata_inverse(raw):
    if b"// BEGIN SOURCE OWNED DEPOT TOOLS SENTINEL NORMALIZATION" in raw:
        raw = assembly_inverse(raw, "driver")
    for row in FULL_METADATA_HISTORY:
        current, old = row["newRaw"].encode(), row["oldRaw"].encode()
        if hashlib.sha256(current).hexdigest() != row["newSha256"] or hashlib.sha256(old).hexdigest() != row["oldSha256"] or raw.count(current) != 1:
            raise AssertionError("FULL_METADATA_INVERSE:" + row["name"])
        raw = raw.replace(current, old, 1)
    return raw


def normalized(raw):
    return raw.replace(b'\r\n', b'\n')


