def fixed61_controller_inverse(raw):
    begin = b"// BEGIN FIXED EXPECTED DEFAULTS BINDING\n"
    end = b"// END FIXED EXPECTED DEFAULTS BINDING\n\n"
    assert raw.count(begin) == 1 and raw.count(end) == 1
    raw = re.sub(re.escape(begin) + rb".*?" + re.escape(end), b"", raw, count=1, flags=re.S)
    imported = "import * as expectedDefaults from \"./expected-defaults.mjs\";\n".encode()
    assert raw.count(imported) == 1
    raw = raw.replace(imported, b"", 1)
    for row in FIXED61_CONTROLLER_HISTORY:
        current, old = row["newRaw"].encode(), row["oldRaw"].encode()
        assert hashlib.sha256(current).hexdigest() == row["newSha256"] and hashlib.sha256(old).hexdigest() == row["oldSha256"]
        assert raw.count(current) == 1
        raw = raw.replace(current, old, 1)
    assert len(raw) == 86610
    assert hashlib.sha256(raw).hexdigest() == "88fb25fede8b99c89fa3b4b47e98eb2a987aa279c578cd22ab5af26329f165c7"
    return raw


def parent_metadata_controller_inverse(raw):
    raw = fixed61_controller_inverse(raw)
    begin = b"\n// BEGIN PRIVATE PARENT METADATA VERIFICATION\n"
    end = b"// END PRIVATE PARENT METADATA VERIFICATION\n\n"
    assert raw.count(begin) == 1 and raw.count(end) == 1
    raw = re.sub(re.escape(begin) + rb".*?" + re.escape(end), b"", raw, count=1, flags=re.S)
    for row in PARENT_METADATA_CONTROLLER_HISTORY:
        current, old = row["newRaw"].encode(), row["oldRaw"].encode()
        assert hashlib.sha256(current).hexdigest() == row["newSha256"] and hashlib.sha256(old).hexdigest() == row["oldSha256"]
        assert raw.count(current) == 1
        raw = raw.replace(current, old, 1)
    assert len(raw) == 61855
    assert hashlib.sha256(raw).hexdigest() == "a74f98f96aba8e63da8ca67021c16c761d57cb85b2f18e622ff5737adb3f5f02"
    return raw


def parent_engine_controller_inverse(raw):
    begin = b'// BEGIN ACTUAL PARENT ENGINE CREATION\n'
    end = b'// END ACTUAL PARENT ENGINE CREATION\n'
    assert raw.count(begin) == 1 and raw.count(end) == 1
    start, finish = raw.index(begin), raw.index(end) + len(end)
    block = raw[start:finish]
    assert len(block) == 18848
    assert hashlib.sha256(block).hexdigest() == 'bca62938d2ade4babfafe2487dc949305852ed95a6572ee5e52bedcc596feb97'
    raw = raw[:start] + raw[finish + 1:]
    assert len(raw) == 94614
    assert hashlib.sha256(raw).hexdigest() == 'fcf7c8e17f4258b89372da11cbafc4e283e53f3d11dfb0c1f16a934e35f56142'
    return raw


def controller_primitives_inverse(raw):
    raw = assembly_inverse(raw, "controller")
    raw = parent_engine_controller_inverse(raw)
    raw = parent_metadata_controller_inverse(raw)
    # Exact clock import + two finite accounting blocks; no clock source or
    # lease semantics are replaced. Then retain the whole older23ee chain.
    clock_blocks = (
        b'import {\n  WORKFLOW_CLOCK_ENV,\n  readWorkflowClock,\n  intersectWorkflowClock,\n} from "./workflow-clock.mjs";\n',
        b'  // BEGIN FIRST WORKFLOW CLOCK INTERSECTION\n  // The checked workflow is the origin of this accounting record. It cannot\n  // open either code gate or replace source/native qualification authority.\n  need(!owner.workflowClock, "WORKFLOW_CLOCK_REUSE");\n  const workflowClock = readWorkflowClock(\n    process.env[WORKFLOW_CLOCK_ENV],\n    process.env,\n    Date.now(),\n  );\n  const wholeLease = leases.get(owner.lease);\n  wholeLease.wallEnd = Math.min(wholeLease.wallEnd, workflowClock.wallEndMs);\n  bootstrapState(bootstrap);\n  const clockProbeMonoStart = performance.now();\n  // END FIRST WORKFLOW CLOCK INTERSECTION\n',
        b'  // BEGIN FIRST WORKFLOW CLOCK NATIVE PROJECTION\n  const inheritedEnds = intersectWorkflowClock(\n    workflowClock,\n    sample.monotonic,\n    clockProbeMonoStart,\n    wholeLease,\n    Date.now(),\n    performance.now(),\n  );\n  wholeLease.wallEnd = inheritedEnds.wallEnd;\n  wholeLease.monoEnd = inheritedEnds.monoEnd;\n  owner.workflowClock = workflowClock;\n  bootstrapState(bootstrap);\n  // END FIRST WORKFLOW CLOCK NATIVE PROJECTION\n',
    )
    for block in clock_blocks:
        assert raw.count(block) == 1
        raw = raw.replace(block, b'', 1)
    assert len(raw) == 60698
    assert hashlib.sha256(raw).hexdigest() == 'bbb1e7bfdd3aaa56c745940ddba1856fb02b40ddb135b6e1266f405e3ba94db1'
    begin = b'// BEGIN CLOSED FULL SDK SOURCE CONTROLLER\n'
    end = b'// END CLOSED FULL SDK SOURCE CONTROLLER\n\n'
    assert raw.count(begin) == 1 and raw.count(end) == 1
    raw = re.sub(re.escape(begin) + rb'.*?' + re.escape(end), b'', raw, count=1, flags=re.S)
    raw = raw.replace(b'// Closed source controller. Public admission, native qualification, engine,\n// package, transport and SDK record/publication authority remain unavailable.\n',
                      b'// Inactive primitives only. There is intentionally no source-session issuer,\n// phase launcher, coordinator, API transport, record writer or SDK admission.\n', 1)
    raw = raw.replace(b'import { randomBytes, randomUUID, createHash } from "node:crypto";\n',
                      b'import { randomBytes } from "node:crypto";\n', 1)
    for line in (b'import { spawn, ChildProcess } from "node:child_process";\n',
                 b'import { fileURLToPath } from "node:url";\n',
                 b'import * as checkpoint from "./current-source-helpers/scripts/lib/cef-engineering-checkpoint.mjs";\n'):
        assert raw.count(line) == 1
        raw = raw.replace(line, b'', 1)
    raw = raw.replace(b'const sourceSessions = new WeakMap(); // Sole writer: actual runSourcePhase creation path.\n',
                      b'const sourceSessions = new WeakMap(); // No production writer exists.\n', 1)
    for indent in (b'  ', b'    '):
        block = indent + b'if (state.source.operationToken)\n' + indent + b'  await work(token, state, () =>\n' + indent + b'    recheckSourceReceipt(state.sourceReceipt, state.leaseToken),\n' + indent + b'  );\n'
