def isolated_source_model(context, profile):
    """Execute real internal functions in separate maps; never production issuance."""
    module = types.ModuleType('full_source_fixture_model')
    module.__file__ = str(HERE / 'full_sdk_source.py')
    exec(compile((HERE / 'full_sdk_source.py').read_bytes(), module.__file__, 'exec'), module.__dict__)
    module.sys = types.SimpleNamespace(modules={module.__name__: module, 'full_sdk_source': module})
    module.time = types.SimpleNamespace(time=lambda: 100.0, monotonic=lambda: 100.0)
    c = copy.deepcopy(context)
    c.update(wallWholeEnd=21700, monotonicWholeEnd=21700, wallWorkEnd=7300,
             monotonicWorkEnd=7300, wallAcquisitionEnd=4600, monotonicAcquisitionEnd=4600)
    p = {'python': copy.deepcopy(profile['python']), 'target': profile['target'],
         'sourceGn': {'sourceId': c['sourceId'], 'hostTools': {'node': profile['node']},
                      'executionPolicy': dict(hostLoaderClosureApproved=True,
                                              gitConfigurationApproved=True,
                                              sourceHookCommandClosureApproved=True),
                      'limits': {'outputBytes': 67108864}}}
    root = Path.cwd()
    raw = json.dumps(c).encode()
    memory = {'context': raw, 'reads': [], 'reports': [], 'reportError': None}
    def held(path, clock, *args, **kwargs):
        memory['reads'].append(path)
        clock.remaining()
        value = memory['context'] if path.name == 'context.json' else b'{"success":true}'
        expected = kwargs.get('sha256')
        if expected is not None:
            module.need(hashlib.sha256(value).hexdigest() == expected, 'FIXTURE_HASH')
        return {}, value
    def save(path, value):
        memory['reports'].append((path, value))
        if memory['reportError'] is not None:
            raise memory['reportError']
    data = types.SimpleNamespace(plain=lambda value: value,
                                 signature=lambda value: (value.st_dev, value.st_ino),
                                 held=held, save=save)
    native = {'parent': types.SimpleNamespace(is_set=lambda: False)}
    birth = object()
    state = dict(key=module._root_key(root), root=root,
                 rootId=(root.stat().st_dev, root.stat().st_ino), here=HERE,
                 rootFence=module._capture_root_fence(root), role=module._OPERATION,
                 birth=birth, native=native, context=c, profile=p,
                 clock=types.SimpleNamespace(remaining=lambda: 600.0, wall_end=7300, mono_end=7300),
                 contextSha=hashlib.sha256(raw).hexdigest(), contextRaw=raw,
                 contextSemantic=module._semantic(c), profileSemantic=module._semantic(p),
                 held=[], data=data, failed=False, primary=None, closed=False, epoch=0)
    state['producer'] = types.SimpleNamespace(source_capacity=lambda *args: None,
        verify_source_host_closure=lambda *args, **kwargs: {'fixtureOnly': True},
        validate_source_gn_result=lambda value, recipe: value)
    # These are isolated test map writes, not a creator or token in subject.
    module._ACTIVE[state['key']] = state
    module._BIRTHS[birth] = native
    return module, state, memory


def owned_filesystem_model(context, profile, root):
    """Actual filesystem/save body; only native handles and kernel are modeled."""
    model, state, memory = isolated_source_model(context, profile)
    del model._ACTIVE[state['key']]
    fence = model._capture_root_fence(root)
    state.update(root=root, key=model._root_key(root), rootId=fence[0][1][:2], rootFence=fence, role='launcher')
    native = dict(parent=types.SimpleNamespace(is_set=lambda: False, close=lambda: None),
                  own=object(), pid=1, creationFiletime='1', parentCreationFiletime='1')
    state['native'] = native
    model._ACTIVE[state['key']] = state
    model._BIRTHS[state['birth']] = native
    tree = ast.parse((HERE / 'acquire.py').read_bytes())
    save = next(node for node in tree.body if isinstance(node, ast.FunctionDef) and node.name == 'save')
    namespace = {'Path': Path, 'json': json}
    exec(compile(ast.Module(body=[save], type_ignores=[]), '<actual-acquire-save>', 'exec'), namespace)
    state['data'].save = namespace['save']
    model.job = types.SimpleNamespace(close=lambda handle: True,
                                     checked=lambda ok, code: model.need(ok, code),
                                     run_job=lambda *args, **kwargs: (_ for _ in ()).throw(AssertionError('NO_NATIVE_JOB_ALLOWED')))
    tree = ast.parse((HERE / 'full_sdk_source.py').read_bytes())
    names = {'_close_source_entry', '_run_source_launcher', '_run_operation'}
    functions = [node for node in tree.body if isinstance(node, ast.FunctionDef) and node.name in names]
    for function in functions:
        function.body = [node for node in function.body if not isinstance(node, ast.Import)]
    exec(compile(ast.Module(body=functions, type_ignores=[]), '<actual-bodies-modeled-native-import-only>', 'exec'), model.__dict__)
    return model, state, memory


def environment_filesystem_model(context, profile, root):
    """Real owned files/rows/script; private registry and absent VS host are modeled."""
    import acquire as data
    import environment
    model, state, memory = owned_filesystem_model(context, profile, root)
    state['role'] = 'runtime-closure'
    base = json.loads((HERE / 'profile.json').read_bytes())
    state['profile'].update(sdkVersion=base['sdkVersion'], toolset=base['toolset'],
                            vsRoot=str(root / 'installed-vs'), limits=base['limits'])
    state['profile']['python']['path'] = str(root / 'python/python.exe')
    state['profileSemantic'] = model._semantic(state['profile'])
    state['clock'].wall_end = time.time() + 600
    state['clock'].mono_end = time.monotonic() + 600
    (root / 'context.json').write_bytes(state['contextRaw'])
    host = {'C:/Windows', 'C:/Windows/System32'}
    def plain(value, exists=True):
        if __import__('os').name != 'nt' and str(value) in host:
            return types.SimpleNamespace(is_dir=lambda: True)
        return data.plain(value, exists)
    for cpu in environment.CPUS:
        rows = environment.rows(root, state['profile'], cpu)
        for key in ('INCLUDE', 'LIB', 'LIBPATH', 'Path'):
            for value in rows[key].split(';'):
                if value not in host:
                    Path(value).mkdir(parents=True, exist_ok=True)
    state['data'] = types.SimpleNamespace(plain=plain, signature=data.signature,
                                          held=data.held, save=data.save)
    return model, state, memory


def run_environment_worker(model, state, before=False, before_retention=False):
    """Actual worker/bridge. Only acquisition inventory/projection and native scope are modeled."""
    import acquire as data
    import environment
    raw = normalized((HERE / 'producer.py').read_bytes())
    if before:
        raw = full_environment_inverse(raw, 'producer')
    if before_retention:
        for label in ('BEFORE PROGRESS', 'BEFORE REPORT'):
            pattern = rb'(?m)^        # BEGIN OWNED FULL SOURCE ENVIRONMENT RETENTION ' + label.encode() + rb'\n.*?^        # END OWNED FULL SOURCE ENVIRONMENT RETENTION ' + label.encode() + rb'\n'
            raw, count = re.subn(pattern, b'', raw, count=1, flags=re.S)
            assert count == 1
        raw = raw.replace(b'        if progress is not None and environment_retention_allowed:\n', b'        if progress is not None:\n', 1)
        raw = raw.replace(b'        if environment_retention_allowed:\n            retain(root, role + "-result.json", result)\n', b'        retain(root, role + "-result.json", result)\n', 1)
    tree = ast.parse(raw)
    names = {'data_worker', 'failure', 'retain', '_full_source_bridge'}
    functions = [node for node in tree.body if isinstance(node, ast.FunctionDef) and node.name in names]
    class Progress:
        closeFailure = False
        def __call__(self, *args, **kwargs):
            state.setdefault('fixtureProgress', []).append(args[0])
            if state.get('fixtureProgressHook') is not None:
                state['fixtureProgressHook'](args[0])
    shim = types.ModuleType('environment')
    shim.__dict__.update(environment.__dict__)
    shim.installed_inventory = lambda *args: {'modeledNativeInventory': True}
    extract = types.SimpleNamespace(FILE_CLOSE_FAILURE=False,
                                    runtime_projection=lambda *args: {'modeledNativeProjection': True})
    namespace = dict(sys=types.SimpleNamespace(addaudithook=lambda _: None,
                                              modules={**model.sys.modules, 'extract': extract}),
                     data=data, time=time, re=re, _FULL_SOURCE_MODULE=model,
                     no_execution=lambda *args: None, COMMAND_INVENTORY_REPORTING_FAILURE=False,
                     RuntimeProgress=lambda *args: Progress(),
                     verified_sources=lambda root: model._verified_active_sources(root))
    exec(compile(ast.Module(body=functions, type_ignores=[]), '<actual-runtime-closure-model-native>', 'exec'), namespace)
    classify = namespace['failure']
    def observe(error):
        state['fixtureException'] = error
        return classify(error)
    namespace['failure'] = observe
    with patch.dict(sys.modules, {'environment': shim, 'extract': extract}):
        return namespace['data_worker']('runtime-closure', state['root'], state['context'], state['profile'], state['clock'])




