def source_acquisition_inverse(raw, name):
    raw = full_bootstrap_cache_inverse(raw, name)
    spec = SOURCE_ACQUISITION_HISTORY[name]
    for row in spec['rows']:
        new, old = row['newRaw'].encode(), row['oldRaw'].encode()
        assert hashlib.sha256(new).hexdigest() == row['newSha256'], 'ASSEMBLY_INVERSE_SOURCE_ACQUISITION_PIN'
        assert hashlib.sha256(old).hexdigest() == row['oldSha256'], 'ASSEMBLY_INVERSE_SOURCE_ACQUISITION_PIN'
        assert raw.count(new) == 1, 'ASSEMBLY_INVERSE_SOURCE_ACQUISITION_COUNT'
        raw = raw.replace(new, old, 1)
    assert len(raw) == spec['bytes'] and hashlib.sha256(raw).hexdigest() == spec['sha256'], 'ASSEMBLY_INVERSE_SOURCE_ACQUISITION_WHOLE'
    return raw
