    def test_old_source_and_kernel_bytes_restore_exactly(self):
        for name, labels in [('producer.py', ('MODE', 'AUTHORITY', 'VERIFIED', 'POLICY',
                                             'ROLE', 'VECTOR', 'CLOSEDVECTOR', 'RECIPE', 'HOST')),
                             ('job.py', ('COMMAND',))]:
            raw = normalized((HERE / name).read_bytes())
            if name == 'producer.py':
                raw = full_environment_inverse(raw, 'producer')
            # Remove only the finite sibling engine bridges before applying the
            # unchanged historical source/kernel inverse and its original pins.
            engine = rb'(?m)^[ ]*# BEGIN CLOSED FULL SDK ENGINE [^\n]+\n[\s\S]*?^[ ]*# END CLOSED FULL SDK ENGINE [^\n]+\n'
            self.assertEqual(len(re.findall(engine, raw)), 3 if name == 'producer.py' else 1)
            raw = re.sub(engine, b'', raw)
            if name == 'producer.py':
                raw = raw.replace(b'# END INACTIVE FULL SDK SOURCE BRIDGE\n\n\n', b'# END INACTIVE FULL SDK SOURCE BRIDGE\n\n', 1)
            restored = raw
            for label in labels:
                begin = ('    # BEGIN INACTIVE FULL SDK SOURCE ' + label + '\n').encode()
                end = ('    # END INACTIVE FULL SDK SOURCE ' + label + '\n').encode()
                self.assertEqual(restored.count(begin), 1)
                self.assertEqual(restored.count(end), 1)
                restored = re.sub(re.escape(begin) + rb'.*?' + re.escape(end), b'', restored, count=1, flags=re.S)
            if name == 'producer.py':
                begin = b'# BEGIN INACTIVE FULL SDK SOURCE BRIDGE\n'
                end = b'# END INACTIVE FULL SDK SOURCE BRIDGE\n\n'
                self.assertEqual(restored.count(begin), 1)
                self.assertEqual(restored.count(end), 1)
                restored = re.sub(re.escape(begin) + rb'.*?' + re.escape(end), b'', restored, count=1, flags=re.S)
            size, digest = BASELINE_PINS[name]
            self.assertEqual(len(restored), size)
            self.assertEqual(hashlib.sha256(restored).hexdigest(), digest)
        new = ast.parse((HERE / 'job.py').read_bytes())
        def kernel(tree):
            return ast.dump(next(node for node in tree.body if isinstance(node, ast.FunctionDef) and node.name == 'run_job'), include_attributes=False)
        self.assertEqual(hashlib.sha256(kernel(new).encode()).hexdigest(), RUN_JOB_AST_SHA256)

    def test_c9_source_program_inverse_is_finite_and_tamper_denies(self):
        raw = (HERE / 'full-sdk-source-driver.mjs').read_bytes()
        previous_cache = full_bootstrap_cache_inverse(raw, 'driver')
        rows = self.p['sourceProgramCarryforward']['programs']
        self.assertTrue(self.p['sourceProgramCarryforward']['implemented'])
        self.assertFalse(self.p['sourceProgramCarryforward']['nativeQualified'])
        self.assertFalse(self.p['sourceProgramCarryforwardQualified'])
        self.assertTrue(self.p['derivation']['apache4D61Carried'])
        self.assertEqual([row['name'] for row in rows], ['bootstrapProgram', 'dependencyHookArguments', 'boundGnArguments'])
        for actual, expected in zip(SOURCE_PROGRAM_HISTORY, rows):
            for field in ('name', 'oldSha256', 'newSha256', 'reviewedSourceSha256'):
                self.assertEqual(actual[field], expected[field])
            current = actual['newRaw'].encode()
            self.assertEqual(previous_cache.count(current), 1)
            needle = current.splitlines(keepends=True)[0] if actual['name'] in ('bootstrapProgram', 'boundGnArguments') else current
            self.assertEqual(raw.count(needle), 1)
            with self.assertRaisesRegex(AssertionError, 'SOURCE_PROGRAM_INVERSE|ASSEMBLY_INVERSE'):
                source_program_inverse(raw.replace(needle, b'/* tampered */' + needle[1:], 1))
            with self.assertRaisesRegex(AssertionError, 'SOURCE_PROGRAM_INVERSE|ASSEMBLY_INVERSE'):
                source_program_inverse(raw + b'\n' + needle)
            if actual['name'] != 'bootstrapProgram':
                self.assertEqual(actual['newSha256'], actual['reviewedSourceSha256'])
        self.assertNotIn(b'fullBootstrapAuthority(', source_program_inverse(raw).split(b'// BEGIN CLOSED FULL SDK SOURCE BODY')[0])

    def test_actual_generated_bootstrap_context_guard_keeps_full_identity_and_original_ends(self):
        program = SOURCE_PROGRAM_HISTORY[0]['newRaw']
        function = program[program.index('def context():\n'):program.index('\ndef write_new(')]
        # Execute only the actual emitted context function against a data-only model.
        # Fixture P values and held bytes cannot register any production profile.
        bound = dict(self.context, wallWorkEnd=91, monotonicWorkEnd=81)
        root = Path('/owned')
        environment = {key: str(root / 'source-caches' / relative) for key, relative in (
            ('CIPD_CACHE_DIR', 'cipd'), ('VPYTHON_VIRTUALENV_ROOT', 'vpython'),
            ('LOCALAPPDATA', 'local'), ('APPDATA', 'roaming'), ('XDG_CACHE_HOME', 'xdg'))}
        environment['CIPD_CONFIG_FILE'] = str(root / 'source-caches/cipd.cfg')
        for change in ('none', 'disabled', 'mode', 'ref', 'context'):
            with self.subTest(change=change):
                value = dict(bound)
                policy = {'enabled': change != 'disabled', 'fullContext': bound}
                if change == 'mode':
                    value['mode'] = 'private-compiler-input-qualification'
                elif change == 'ref':
                    value['ref'] = 'refs/heads/codex/windows-arm-engine-qualification-20261101'
                elif change == 'context':
                    value['runId'] = '999'
                raw = json.dumps(value).encode()
                policy['contextSha'] = hashlib.sha256(raw).hexdigest()
                clocks = []
                def clock(wall, mono):
                    clocks.append((wall, mono))
                    return (wall, mono)
                def need(value, code):
                    if not value:
                        raise AssertionError(code)
                def held(file, unused_clock, **kwargs):
                    data = raw if file.name == 'context.json' else b''
                    need(hashlib.sha256(data).hexdigest() == kwargs['sha256'], 'HELD_PIN')
                    return None, data
                scope = {'P': policy, 'ROOT': root, 'json': json, 'hashlib': hashlib, 'Path': Path,
                         'time': types.SimpleNamespace(time=lambda: 1, monotonic=lambda: 2),
                         'os': types.SimpleNamespace(environ=environment),
                         'data': types.SimpleNamespace(Clock=clock, need=need, plain=lambda unused: None),
                         'extract': types.SimpleNamespace(held=held)}
                exec(compile(function, '<actual-emitted-bootstrap-context>', 'exec'), scope)
                if change == 'none':
                    self.assertEqual(scope['context'](), (91, 81))
                    self.assertEqual(clocks, [(6, 7), (91, 81)])
                else:
                    with self.assertRaisesRegex(AssertionError, 'FULL_BOOTSTRAP_AUTHORITY'):
                        scope['context']()
                    self.assertEqual(clocks, [(6, 7)])

